const start = $today.startOf('month');
const end0 = $today.minus({days:1});
const end = end0 < start ? start : end0;
const label = start.toFormat('MMM d') + ' - ' + end.toFormat('MMM d, yyyy') + ' (Month-to-Date)';
return [{json:{periodStart:start.toISODate(), periodEnd:end.toISODate(), periodLabel:label, periodType:'month_to_date'}}];

const start = $today.startOf('week').minus({weeks:1});
const end = start.plus({days:6});
const label = start.toFormat('MMM d') + ' - ' + end.toFormat('MMM d, yyyy') + ' (Weekly)';
return [{json:{periodStart:start.toISODate(), periodEnd:end.toISODate(), periodLabel:label, periodType:'weekly'}}];

const start = $today.startOf('month').minus({months:1});
const end = $today.startOf('month').minus({days:1});
const label = start.toFormat('MMMM yyyy') + ' (Monthly)';
return [{json:{periodStart:start.toISODate(), periodEnd:end.toISODate(), periodLabel:label, periodType:'monthly'}}];

return items.filter(i => {
  const j=i.json||{};
  const status=String(j.Status||'').toLowerCase();
  const platform=String(j.Platform||'').toLowerCase();
  // Raw_Sheet_ID is required. TikTok_Advertiser_ID is preferred but not required for file ingestion.
  return status==='active' && j.Raw_Sheet_ID && (j.TikTok_Advertiser_ID || platform.includes('tiktok') || j.TikTok_Export_Folder_ID || j.TikTok_Drive_Folder_ID);
});

const brand = $('Loop brands').item.json;
const period = $('Set Period').first().json;
function esc(s){return String(s||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");}
const brandName = brand.Brand_Name || brand.name || '';
const folderId = brand.TikTok_Export_Folder_ID || brand.TikTok_Drive_Folder_ID || brand.Export_Folder_ID || '';
let q = "trashed = false";
q += " and (mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' or mimeType = 'application/vnd.ms-excel' or mimeType = 'text/csv' or mimeType = 'application/vnd.google-apps.spreadsheet')";
if (folderId) q += ` and '${esc(folderId)}' in parents`;
if (brandName) q += ` and name contains '${esc(brandName)}'`;
q += " and (name contains 'TikTok' or name contains 'Tiktok' or name contains 'tiktok')";
return [{ json: { ...brand, ...period, driveQuery: q, exportFolderId: folderId, expectedFileName: `${brandName} TikTok export`, Pulled_At: new Date().toISOString() } }];

const ctx = $('Build Drive Search Query').first().json;
const files = items.map(i => i.json || {}).filter(f => f.id && f.name);
if (!files.length) {
  return [{ json: { ...ctx, skip: true, error: `No TikTok export file found in Drive for ${ctx.Brand_Name}. Query: ${ctx.driveQuery}` } }];
}
files.sort((a,b) => new Date(b.modifiedTime || 0) - new Date(a.modifiedTime || 0));
const f = files[0];
return [{ json: { ...ctx, exportFileId: f.id, exportFileName: f.name, exportMimeType: f.mimeType, exportModifiedTime: f.modifiedTime, exportUrl: f.webViewLink, skip: false } }];

function cleanKey(k){return String(k||'').toLowerCase().replace(/[%()]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');}
function pick(row, aliases){
  const map={};
  for(const [k,v] of Object.entries(row||{})) map[cleanKey(k)] = v;
  for(const a of aliases){const key=cleanKey(a); if(map[key]!==undefined && map[key]!==null && map[key] !== '') return map[key];}
  return '';
}
function num(v){
  if(v==null||v==='')return 0;
  if(typeof v==='number') return Number.isFinite(v)?v:0;
  let s=String(v).trim();
  if(!s || s==='-' || s==='--') return 0;
  const pct=s.includes('%');
  s=s.replace(/,/g,'').replace(/EGP|USD|EUR|GBP|ج\.م|جنيه/gi,'').replace(/%/g,'').trim();
  const n=Number(s);
  return Number.isFinite(n)?n:0;
}
function round(n,p){const f=10**p;return Math.round((Number(n)||0)*f)/f;}
function dateVal(v){
  if(v==null||v==='')return '';
  if(typeof v==='number' || (/^\d+(\.\d+)?$/.test(String(v).trim()) && Number(v)>30000)) return new Date((Number(v)-25569)*86400*1000).toISOString().slice(0,10);
  const s=String(v).trim();
  if(/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0,10);
  const fmts=['M/d/yyyy','M/d/yy','MM/dd/yyyy','d/M/yyyy','d/M/yy','dd/MM/yyyy','MMM d, yyyy','MMMM d, yyyy'];
  for(const f of fmts){const dt=DateTime.fromFormat(s,f); if(dt.isValid) return dt.toISODate();}
  const dt=DateTime.fromISO(s); return dt.isValid ? dt.toISODate() : '';
}
